insert into public.modules ("module_id","title","grade_class","term","order","weeks","output","content_standard","performance_standard","unlocked") values ('G9-M1','Introduction to Film and Cinema','G9','Term 1',1,8,'A film critique of one short or full length film.','The learners understand film history, its genres, and the elements of film criticism, and recognize cinema''s contribution to culture and society.','The learners produce a film review or critical essay on a commercial or short film.',true)
